  await review.getByRole('button', {name:'Save bookmark'}).click();
  if (!(await page.locator('#bookmarkCount').getByText('2 bookmarks').isVisible())) throw new Error('count not updated');
  const firstCard = page.locator('#cards .card').first();
  if (!(await firstCard.getByText('travel', {exact:true}).isVisible())) throw new Error('tag not saved');
  console.log('inline save, duplicate detection, and suggested-tag save: ok');
  await browser.close();
})();
