  const page = await browser.newPage({viewport:{width:1280,height:900}});
  await page.goto('http://127.0.0.1:4001/?state=tagging', {waitUntil:'networkidle'});
  await page.locator('#quickUrl').fill('https://roaming.example/rome');
  await page.locator('#quickContinue').click();
  const review = page.locator('#reviewStep');
  await review.getByLabel('Tags', {exact:true}).waitFor({state:'visible'});
  await review.getByLabel('Tags', {exact:true}).fill('tra');
  await review.getByRole('button', {name:'travel', exact:true}).click();
  await review.getByRole('button', {name:'Save bookmark'}).click();
  if ((await page.locator('#bookmarkCount').textContent()) !== '2 bookmarks') throw new Error('count not updated');
  if (!(await page.locator('#cards .card').first().getByText('travel', {exact:true}).isVisible())) throw new Error('tag not saved');
  console.log('suggested-tag save: ok');
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
