+<!doctype html>
+<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Keepwell — Compare unreachable-page behavior</title><style>
+  :root{--ink:#1d2722;--muted:#647069;--line:#dce2dd;--paper:#fffef9;--wash:#f2f3ec;--green:#245f49;--dark:#194735;--red:#8a3d38;--redwash:#f7e9e6;--amber:#80551f;--amberwash:#fff3dc;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--wash);color:var(--ink)}button,input{font:inherit}.page{width:min(1080px,94vw);margin:0 auto;padding:34px 0 60px}.intro{text-align:center;margin-bottom:26px}.intro h1{margin:0 0 8px;font:500 clamp(30px,4vw,44px)/1.1 Georgia,serif}.intro p{margin:0;color:var(--muted)}.compare{display:grid;grid-template-columns:1fr 1fr;gap:22px}.version{background:var(--paper);border:1px solid var(--line);border-radius:18px;overflow:hidden;box-shadow:0 8px 28px rgba(35,56,45,.07)}.label{padding:10px 16px;background:#e5ebe6;color:var(--dark);font-size:13px;font-weight:750;letter-spacing:.04em;text-transform:uppercase}.app{padding:24px;min-height:480px}.app h2{margin:0 0 16px;font:500 28px Georgia,serif}.savebar{display:flex;gap:8px;padding:8px;border:1px solid var(--line);border-radius:11px;background:white}.savebar input{min-width:0;flex:1;border:0;padding:6px}.savebar input:focus{outline:0}.primary{border:0;border-radius:8px;background:var(--green);color:white;padding:9px 12px;font-weight:700;cursor:pointer}.status{margin-top:18px;padding:15px;border-radius:11px}.status strong{display:block;margin-bottom:5px}.status p{margin:0;font-size:14px;line-height:1.45}.error{background:var(--redwash);border:1px solid #ebccc6;color:#714944}.warning{background:var(--amberwash);border:1px solid #ecd5a8;color:#6f512b}.retry{margin-top:14px;border:1px solid #c8d0ca;border-radius:8px;background:white;padding:9px 12px;color:var(--dark);font-weight:700;cursor:pointer}.fields{margin-top:18px}.fields label{display:block;margin:13px 0 6px;font-size:13px;font-weight:720}.fields input{width:100%;border:1px solid #c8d0ca;border-radius:9px;padding:10px}.fields .primary{margin-top:16px;width:100%}.saved{margin-top:18px;padding:15px;border-radius:11px;background:#e4f1e8;color:var(--dark);font-weight:680}[hidden]{display:none!important}@media(max-width:760px){.compare{grid-template-columns:1fr}.page{width:min(540px,92vw)}}
+</style></head><body><main class="page" data-harness-ready="true"><div class="intro"><h1>What if the page cannot be reached?</h1><p>Try the same unavailable address in both versions.</p></div><section class="compare">
+  <article class="version" id="versionA"><div class="label">Version A</div><div class="app"><h2>Your library</h2><div class="savebar"><input aria-label="Web address in Version A" value="https://offline.example/article"><button class="primary continue">Continue</button></div><div class="status error" hidden><strong>We couldn’t reach this page</strong><p>Nothing was saved because page details and a readable copy could not be captured.</p><button class="retry">Try again</button></div></div></article>
+  <article class="version" id="versionB"><div class="label">Version B</div><div class="app"><h2>Your library</h2><div class="savebar"><input aria-label="Web address in Version B" value="https://offline.example/article"><button class="primary continue">Continue</button></div><div class="status warning" hidden><strong>We couldn’t reach this page yet</strong><p>You can save the address with your own title. There is no saved copy yet; Keepwell will retry automatically.</p></div><div class="fields" hidden><label for="titleB">Title</label><input id="titleB" value="Article to revisit"><label for="notesB">Your notes</label><input id="notesB" value="Try again when the site is back"><button class="primary save">Save without a copy for now</button></div><div class="saved" hidden>Bookmark saved with a warning. Capture will be retried.</div></div></article>
