input:focus, textarea:focus, button:focus-visible, a:focus-visible { outline: 3px solid rgba(226, 157, 66, .45); outline-offset: 2px; }
.button { border: 1px solid transparent; border-radius: 9px; padding: 10px 14px; font-weight: 750; white-space: nowrap; }
.button.primary { color: white; background: var(--green); box-shadow: 0 2px 0 var(--green-dark); }
.button.primary:hover { background: var(--green-dark); }
.button.secondary { color: var(--ink); background: white; border-color: #c8d1ca; }
.button.danger { color: white; background: var(--red); }
.wide { width: 100%; margin-top: 21px; }
.review-credentials { font-size: 12px; }
code { padding: 2px 5px; border-radius: 4px; background: #e8ece8; color: var(--green-dark); }
.site-header { height: 72px; padding: 0 4vw; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line); background: rgba(255,254,249,.96); position: sticky; top: 0; z-index: 10; }
.header-actions { display: flex; align-items: center; gap: 15px; }
.account-email { color: var(--muted); font-size: 13px; }
.icon-button, .text-button { border: 0; padding: 4px; color: var(--green); background: transparent; font-weight: 740; }
.page-shell { width: min(1220px, 94vw); margin: 0 auto; padding: 38px 0 75px; display: grid; grid-template-columns: 190px minmax(0, 1fr); gap: 38px; }
.sidebar { display: grid; align-content: start; gap: 7px; position: sticky; top: 106px; }
.nav-button { width: 100%; border: 0; border-radius: 10px; padding: 11px 12px; display: flex; justify-content: space-between; color: var(--muted); background: transparent; text-align: left; }
.nav-button.active { color: var(--green-dark); background: #dfe9e2; font-weight: 780; }
.nav-count { min-width: 25px; padding: 2px 7px; border-radius: 999px; background: rgba(36,95,73,.12); font-size: 12px; text-align: center; }
.page-heading { display: flex; justify-content: space-between; gap: 25px; align-items: end; }
.eyebrow { margin: 0 0 8px; color: var(--green); font-size: 12px; font-weight: 820; letter-spacing: .08em; text-transform: uppercase; }
.page-heading h1 { margin: 0; font: 500 clamp(36px, 5vw, 52px)/1 Georgia, serif; letter-spacing: -1.3px; }
.page-heading p:last-child { margin: 9px 0 0; color: var(--muted); }
.save-bar, .search-bar { display: flex; gap: 9px; align-items: center; padding: 9px; border: 1px solid var(--line); border-radius: 13px; background: var(--paper); box-shadow: 0 4px 16px rgba(35,56,45,.05); }
.save-bar { margin-top: 26px; }
.search-bar { margin-top: 28px; }
.save-bar input, .search-bar input { min-width: 0; flex: 1; border: 0; padding: 6px; background: transparent; }
.save-bar input:focus, .search-bar input:focus { outline: 0; }
.save-bar:focus-within, .search-bar:focus-within { outline: 3px solid rgba(226,157,66,.34); }
.save-bar.invalid { border-color: #c77b72; }
.bar-icon { color: var(--green); font-size: 20px; padding-left: 3px; }
.demo-hint { margin: 7px 4px 0; color: var(--muted); font-size: 12px; }
.field-error { margin: 7px 4px 0; color: var(--red); font-size: 13px; }
.alert { padding: 12px 14px; border-radius: 10px; font-size: 14px; line-height: 1.4; }
.alert strong { display: block; margin-bottom: 3px; }
.alert span { display: block; }
.alert-error, .alert-danger { color: #754a45; background: var(--red-soft); border: 1px solid #ebc9c4; }
.alert-warning { color: #704f25; background: var(--amber-soft); border: 1px solid #ead3a7; }
.alert-info { color: var(--green-dark); background: var(--green-soft); border: 1px solid #c9dbce; }
#searchError { margin-top: 10px; }
.interpretation { margin-top: 10px; padding: 11px 13px; border: 1px solid var(--line); border-radius: 10px; background: #f8f9f5; font-size: 13px; }
.interpretation strong { margin-right: 6px; }
.list-meta { margin: 20px 2px 11px; display: flex; justify-content: space-between; color: var(--muted); font-size: 13px; }
.bookmark-list { display: grid; gap: 12px; }
.bookmark-card { display: grid; grid-template-columns: 52px minmax(0,1fr) auto; gap: 15px; padding: 19px; border: 1px solid var(--line); border-radius: 15px; background: var(--paper); box-shadow: 0 5px 18px rgba(35,56,45,.045); }
.bookmark-icon { width: 50px; height: 50px; border-radius: 11px; display: grid; place-items: center; background: var(--green-soft); color: var(--green-dark); font: 700 22px Georgia, serif; overflow: hidden; }
.bookmark-icon img { width: 100%; height: 100%; object-fit: cover; }
.bookmark-title { margin: 0 0 6px; font-size: 19px; line-height: 1.25; }
.bookmark-title a, .bookmark-title button { color: var(--ink); text-decoration: none; font: inherit; font-weight: 790; border: 0; padding: 0; background: transparent; text-align: left; }
.bookmark-title a:hover, .bookmark-title button:hover { text-decoration: underline; }
.bookmark-description { margin: 0; color: var(--muted); line-height: 1.45; overflow-wrap: anywhere; }
.bookmark-meta { margin-top: 9px; color: var(--green); font-size: 12px; overflow-wrap: anywhere; }
.tag-row, .selected-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.tag-chip { display: inline-flex; align-items: center; padding: 5px 8px; border-radius: 999px; background: var(--green-soft); color: var(--green-dark); font-size: 12px; font-weight: 690; }
.card-actions { display: flex; flex-wrap: wrap; align-content: start; justify-content: flex-end; gap: 7px; max-width: 245px; }
.card-actions .button { padding: 8px 10px; font-size: 12px; }
.card-actions .delete-button { color: var(--red); border-color: #dfb8b3; }
.capture-status { display: inline-flex; align-items: center; gap: 5px; margin-top: 10px; padding: 5px 8px; border-radius: 7px; color: var(--amber); background: var(--amber-soft); font-size: 12px; font-weight: 720; }
.capture-status.ready { color: var(--green-dark); background: var(--green-soft); }
.empty-state { padding: 58px 30px; border: 1px dashed #bac6bd; border-radius: 16px; background: rgba(255,254,249,.72); text-align: center; }
.empty-symbol { width: 72px; height: 72px; margin: 0 auto 20px; border-radius: 50%; display: grid; place-items: center; color: var(--green); background: var(--green-soft); font-size: 30px; }
.empty-state h2 { margin: 0 0 8px; font: 500 27px Georgia, serif; }
.empty-state p { margin: 0 auto 20px; max-width: 440px; color: var(--muted); line-height: 1.5; }
.toast { position: fixed; right: 24px; bottom: 24px; z-index: 50; max-width: min(420px, calc(100vw - 48px)); padding: 13px 16px; border-radius: 10px; color: white; background: #26382f; box-shadow: var(--shadow); font-weight: 680; }
.dialog { width: min(620px, calc(100vw - 28px)); max-height: calc(100vh - 28px); border: 0; border-radius: 18px; padding: 0; background: var(--paper); box-shadow: 0 24px 75px rgba(23,48,35,.26); }
.dialog::backdrop { background: rgba(20,33,26,.5); backdrop-filter: blur(2px); }
.dialog-small { width: min(520px, calc(100vw - 28px)); }
.dialog-content { position: relative; padding: 29px; }
.dialog-close { position: absolute; right: 17px; top: 15px; border: 0; padding: 4px; color: var(--muted); background: transparent; font-size: 26px; line-height: 1; }
.dialog h2 { margin: 0; font: 500 30px/1.15 Georgia, serif; }
.dialog-lead { margin: 8px 0 21px; color: var(--muted); line-height: 1.45; }
.dialog .alert { margin: 14px 0; }
.page-source { display: grid; grid-template-columns: 45px 1fr; gap: 11px; align-items: center; margin: 17px 0; padding: 12px; border: 1px solid var(--line); border-radius: 11px; background: white; }
.source-icon { width: 43px; height: 43px; border-radius: 10px; display: grid; place-items: center; color: var(--green-dark); background: var(--green-soft); font: 700 20px Georgia, serif; }
.page-source strong, .page-source span { display: block; }
.page-source span { margin-top: 3px; color: var(--muted); font-size: 12px; overflow-wrap: anywhere; }
.optional { color: var(--muted); font-weight: 450; }
.tag-input-wrap { position: relative; }
.tag-suggestions { position: absolute; z-index: 3; top: calc(100% + 5px); left: 0; right: 0; overflow: hidden; border: 1px solid var(--line); border-radius: 10px; background: white; box-shadow: 0 11px 28px rgba(35,56,45,.15); }
.tag-suggestions button { width: 100%; border: 0; padding: 10px 12px; color: var(--ink); background: white; text-align: left; }
.tag-suggestions button:hover { background: #edf3ee; }
.selected-tags .tag-chip { gap: 6px; }
.selected-tags button { border: 0; padding: 0; color: currentColor; background: transparent; font-weight: 900; }
.check-row { display: flex; align-items: center; gap: 9px; margin-top: 17px; }
.check-row input { width: 17px; height: 17px; }
.dialog-actions { display: flex; justify-content: flex-end; gap: 9px; margin-top: 23px; }
.danger-text { color: var(--red); }
.archive-dialog { width: min(850px, calc(100vw - 28px)); }
.archive-shell { background: var(--paper); }
.archive-top { position: sticky; top: 0; z-index: 2; padding: 14px 18px; display: flex; justify-content: space-between; gap: 20px; align-items: center; border-bottom: 1px solid var(--line); background: var(--green-soft); }
.archive-top strong, .archive-top span { display: block; }
.archive-top span { margin-top: 3px; color: var(--muted); font-size: 12px; }
.inline-close { position: static; }
.archive-article { width: min(680px, calc(100% - 38px)); margin: 0 auto; padding: 42px 0 65px; }
.archive-article h2 { font-size: clamp(34px, 6vw, 48px); }
.archive-deck { color: #4f5c54; font: 19px/1.5 Georgia, serif; }
.archive-byline { padding-bottom: 18px; border-bottom: 1px solid var(--line); color: var(--muted); font-size: 13px; }
.archive-article img { width: 100%; max-height: 380px; margin: 15px 0; border-radius: 12px; object-fit: cover; }
.archive-body { font: 17px/1.72 Georgia, serif; color: #344139; }
.archive-body p { margin: 0 0 18px; }
@media (max-width: 820px) {
  .page-shell { grid-template-columns: 1fr; gap: 21px; }
  .sidebar { position: static; grid-template-columns: 1fr 1fr; }
  .bookmark-card { grid-template-columns: 48px minmax(0,1fr); }
  .card-actions { grid-column: 2; justify-content: flex-start; max-width: none; }
}
@media (max-width: 580px) {
  .site-header { padding: 0 17px; }
  .account-email { display: none; }
  .page-shell { width: calc(100vw - 26px); padding-top: 25px; }
  .save-bar, .search-bar { flex-wrap: wrap; }
  .save-bar input, .search-bar input { flex-basis: calc(100% - 35px); }
  .save-bar .button, .search-bar .button { width: 100%; }
  .bookmark-card { padding: 15px; grid-template-columns: 42px minmax(0,1fr); }
  .bookmark-icon { width: 40px; height: 40px; }
  .dialog-content { padding: 25px 21px; }
  .dialog-actions { flex-direction: column-reverse; }
  .dialog-actions .button { width: 100%; }
}

