  const take = () => tokens[cursor++];
  const startsOperand = token => token && (token.type === 'TERM' || token.type === '(' || token.type === 'NOT');

  function primary() {
    const token = take();
    if (!token) throw new SearchSyntaxError('Add another word or condition to finish this search.');
