export function describeSearch(ast) {
  if (!ast) return [];
  function text(node) {
    switch (node.type) {
      case 'text': return `text contains “${node.value}”`;
      case 'phrase': return `exact phrase “${node.value}”`;
      case 'tag': return `tag exactly “${node.value}”`;
